// Subsequence scoring for the command palette: every query character must
// appear in order; consecutive hits, word starts and an early first hit score
// higher. Returns 0 when the query does not match.
function fuzzyScore(query, text) {
  const q = query.trim().toLowerCase();
  if (!q) return 1;
  const t = text.toLowerCase();
  let ti = 0, score = 0, streak = 0;
  for (let qi = 0; qi < q.length; qi++) {
    const idx = t.indexOf(q[qi], ti);
    if (idx < 0) return 0;
    const wordStart = idx === 0 || /[\s\-_/.]/.test(t[idx - 1]);
    streak = idx === ti ? streak + 1 : 0;
    score += 1 + streak * 2 + (wordStart ? 3 : 0) - Math.min(3, (idx - ti) * 0.25);
    ti = idx + 1;
  }
  if (t.startsWith(q)) score += 10;
  return Math.max(0.01, score / (1 + t.length / 40));
}

// <nk-cmdk id="palette" placeholder="Search or type a command …"></nk-cmdk>
// palette.commands = [
//   { group: 'Pages',   items: [{ id: 'mvp', icon: '🚀', label: 'NotionKit MVP', keywords: 'project' }] },
//   { group: 'Actions', items: [{ id: 'theme', icon: '🌙', label: 'Toggle theme', shortcut: '⌘⇧L', action: () => … }] },
// ];
// → <div class="nk-cmdk-backdrop open"><div class="nk-cmdk"><div class="nk-cmdk-input-row">🔍<input><kbd>esc</kbd></div>
//     <div class="nk-cmdk-list">…</div><div class="nk-cmdk-footer">…</div></div></div>
// mod+K toggles (attribute `hotkey`), ↑↓ move, Enter picks (nk-command +
// item.action), Escape / backdrop close. Fuzzy subsequence search over
// label + keywords. Put the element directly under <body>.
class NkCmdk extends NkElement {
  static get observedAttributes() { return ['open', 'hotkey', 'placeholder']; }

  render() {
    this._backdrop = this.createElement('div', ['nk-cmdk-backdrop']);
    this._backdrop.inert = true;
    this._box = this.createElement('div', ['nk-cmdk'], { role: 'dialog', 'aria-modal': 'true', 'aria-label': 'Command palette' });
    const row = this.createElement('div', ['nk-cmdk-input-row']);
    const glass = document.createElement('span');
    glass.style.fontSize = '15px';
    glass.textContent = '🔍';
    this._input = this.createElement('input', [], { type: 'text', autocomplete: 'off', role: 'combobox', 'aria-expanded': 'true', 'aria-autocomplete': 'list' });
    const esc = this.createElement('kbd', ['nk-kbd']);
    esc.textContent = 'esc';
    row.append(glass, this._input, esc);
    this._list = this.createElement('div', ['nk-cmdk-list'], { role: 'listbox', id: 'list' });
    this._input.setAttribute('aria-controls', 'list');
    this._footer = this.createElement('div', ['nk-cmdk-footer']);
    const footerSlot = this.createElement('slot', [], { name: 'footer' });
    footerSlot.innerHTML = '<span><kbd class="nk-kbd">↑</kbd><kbd class="nk-kbd">↓</kbd> navigate</span><span><kbd class="nk-kbd">↵</kbd> open</span><span><kbd class="nk-kbd">⌘</kbd><kbd class="nk-kbd">K</kbd> toggle</span>';
    this._footer.appendChild(footerSlot);
    this._box.append(row, this._list, this._footer);
    this._backdrop.appendChild(this._box);
    this._wrapper.appendChild(this._backdrop);
    this._commands = [];
    this._index = 0;
    this._syncAttrs();
    this._renderList();
    this._syncOpen();
  }

  _syncAttrs() { this._input.placeholder = this.getAttribute('placeholder') || 'Search or type a command …'; }

  /** Filtered, flat list in group order, best matches first within a group. */
  results() {
    const q = this._input?.value ?? '';
    const out = [];
    for (const group of this._commands) {
      const scored = (group.items || []).map(item => ({ item, group: group.group, score: fuzzyScore(q, `${item.label} ${item.keywords || ''}`) })).filter(r => r.score > 0);
      scored.sort((a, b) => b.score - a.score);
      out.push(...scored);
    }
    return out;
  }

  _renderList() {
    if (!this._list) return;
    const results = this.results();
    this._index = Math.min(this._index, Math.max(0, results.length - 1));
    this._list.replaceChildren();
    if (!results.length) {
      const empty = this.createElement('div', ['nk-cmdk-empty']);
      empty.textContent = `No results for “${this._input.value}”`;
      this._list.appendChild(empty);
      this._input.removeAttribute('aria-activedescendant');
      return;
    }
    let lastGroup = null;
    results.forEach((r, i) => {
      if (r.group && r.group !== lastGroup) {
        const g = this.createElement('div', ['nk-cmdk-group']);
        g.textContent = r.group;
        this._list.appendChild(g);
        lastGroup = r.group;
      }
      const el = this.createElement('div', ['nk-cmdk-item'], { role: 'option', id: `opt-${i}`, 'data-index': i });
      el.classList.toggle('selected', i === this._index);
      el.setAttribute('aria-selected', i === this._index ? 'true' : 'false');
      const icon = this.createElement('span', ['m-icon']);
      icon.textContent = r.item.icon || '';
      const label = document.createElement('span');
      label.textContent = r.item.label;
      el.append(icon, label);
      if (r.item.shortcut) { const sc = this.createElement('span', ['m-shortcut']); sc.textContent = r.item.shortcut; el.appendChild(sc); }
      this._list.appendChild(el);
    });
    this._input.setAttribute('aria-activedescendant', `opt-${this._index}`);
  }

  _move(dir) {
    const n = this.results().length;
    if (!n) return;
    this._index = (this._index + dir + n) % n;
    for (const el of this._list.querySelectorAll('.nk-cmdk-item')) {
      const on = Number(el.dataset.index) === this._index;
      el.classList.toggle('selected', on);
      el.setAttribute('aria-selected', on ? 'true' : 'false');
      if (on) el.scrollIntoView({ block: 'nearest' });
    }
    this._input.setAttribute('aria-activedescendant', `opt-${this._index}`);
  }

  pick(index = this._index) {
    const r = this.results()[index];
    if (!r) return;
    const query = this._input.value;
    this.close();
    const ok = this.emit('nk-command', { id: r.item.id ?? r.item.label, item: r.item, query });
    if (ok && typeof r.item.action === 'function') r.item.action(r.item);
  }

  _matchesHotkey(e) {
    const spec = (this.getAttribute('hotkey') || 'mod+k').toLowerCase().split('+');
    const key = spec.pop();
    const mod = spec.includes('mod') ? (e.metaKey || e.ctrlKey) : true;
    const shift = spec.includes('shift') ? e.shiftKey : !e.shiftKey;
    const alt = spec.includes('alt') ? e.altKey : !e.altKey;
    return mod && shift && alt && e.key.toLowerCase() === key;
  }

  _syncOpen() {
    const open = this.getBoolAttr('open');
    this._backdrop.classList.toggle('open', open);
    this._backdrop.inert = !open;
    if (open === this._wasOpen) return;
    this._wasOpen = open;
    if (open) {
      this._returnFocus = document.activeElement;
      this._input.value = '';
      this._index = 0;
      this._renderList();
      lockScroll();
      this._undoInert = inertOutside(this);
      requestAnimationFrame(() => this._input.focus({ preventScroll: true }));
    } else {
      unlockScroll();
      this._undoInert?.(); this._undoInert = null;
      const back = this._returnFocus;
      if (back && typeof back.focus === 'function' && back.isConnected) back.focus({ preventScroll: true });
      this._returnFocus = null;
    }
  }

  setupEvents() {
    this._onDocKey = (e) => {
      if (this._matchesHotkey(e)) { e.preventDefault(); this.toggle(); return; }
      if (e.key === 'Escape' && this.getBoolAttr('open')) { e.stopPropagation(); this.close(); }
    };
    this._onInput = () => { this._index = 0; this._renderList(); };
    this._onInputKey = (e) => {
      if (e.key === 'ArrowDown') { e.preventDefault(); this._move(1); }
      else if (e.key === 'ArrowUp') { e.preventDefault(); this._move(-1); }
      else if (e.key === 'Enter') { e.preventDefault(); this.pick(); }
    };
    this._onListClick = (e) => { const el = e.target.closest('.nk-cmdk-item'); if (el) this.pick(Number(el.dataset.index)); };
    this._onListMove = (e) => { const el = e.target.closest('.nk-cmdk-item'); if (el && Number(el.dataset.index) !== this._index) { this._index = Number(el.dataset.index); this._move(0); } };
    this._onListDown = (e) => e.preventDefault();   // keep the input focused
    this._onBackdrop = (e) => { if (e.target === this._backdrop) this.close(); };
    document.addEventListener('keydown', this._onDocKey);
    this._input.addEventListener('input', this._onInput);
    this._input.addEventListener('keydown', this._onInputKey);
    this._list.addEventListener('click', this._onListClick);
    this._list.addEventListener('mousemove', this._onListMove);
    this._list.addEventListener('mousedown', this._onListDown);
    this._backdrop.addEventListener('click', this._onBackdrop);
  }

  teardownEvents() {
    document.removeEventListener('keydown', this._onDocKey);
    this._input?.removeEventListener('input', this._onInput);
    this._input?.removeEventListener('keydown', this._onInputKey);
    this._list?.removeEventListener('click', this._onListClick);
    this._list?.removeEventListener('mousemove', this._onListMove);
    this._list?.removeEventListener('mousedown', this._onListDown);
    this._backdrop?.removeEventListener('click', this._onBackdrop);
    if (this._wasOpen) { unlockScroll(); this._undoInert?.(); this._undoInert = null; this._wasOpen = false; }
  }

  onAttributeChanged(name) {
    if (name === 'open') { this._syncOpen(); this.emit('nk-toggle', { open: this.getBoolAttr('open') }); }
    else this._syncAttrs();
  }

  show() { this.setBoolAttr('open', true); }
  close() { this.setBoolAttr('open', false); }
  toggle() { this.setBoolAttr('open', !this.getBoolAttr('open')); }

  get commands() { return this._commands; }
  set commands(list) { this._commands = Array.isArray(list) ? list : []; this._index = 0; this._renderList(); }
  get open() { return this.getBoolAttr('open'); }
  set open(v) { this.setBoolAttr('open', v); }
  get query() { return this._input?.value ?? ''; }
  set query(v) { if (this._input) { this._input.value = v; this._index = 0; this._renderList(); } }
}

customElements.define('nk-cmdk', NkCmdk);

// <nk-menu>
//   <nk-menu-item type="label">Page</nk-menu-item>
//   <nk-menu-item icon="✏️" shortcut="⌘E" value="rename">Rename</nk-menu-item>
//   <nk-menu-item type="separator"></nk-menu-item>
//   <nk-menu-item icon="🗑️" danger value="delete">Delete</nk-menu-item>
// </nk-menu>
// → <div class="nk-pop nk-menu" role="menu">…</div>
// ↑↓ move between items, Enter selects, nk-select bubbles from the item.
class NkMenu extends NkElement {
  render() {
    this._box = this.createElement('div', ['nk-pop', 'nk-menu'], { role: 'menu' });
    this._box.appendChild(document.createElement('slot'));
    this._wrapper.appendChild(this._box);
  }

  get items() { return [...this.querySelectorAll(':scope > nk-menu-item')].filter(i => i.selectable); }

  setupEvents() {
    this._onKey = (e) => {
      const dir = { ArrowDown: 1, ArrowUp: -1 }[e.key];
      const current = e.target.closest?.('nk-menu-item');
      const items = this.items;
      if (!items.length) return;
      if (dir) {
        e.preventDefault();
        const i = items.indexOf(current);
        items[(i + dir + items.length) % items.length].focus();
      } else if ((e.key === 'Enter' || e.key === ' ') && current) {
        e.preventDefault(); current.select();
      }
    };
    this.addEventListener('keydown', this._onKey);
  }

  teardownEvents() { this.removeEventListener('keydown', this._onKey); }

  /** Focuses the first item (called by a popover when it opens). */
  focusFirst() { this.items[0]?.focus(); }
}

customElements.define('nk-menu', NkMenu);

// <nk-menu-item icon="✏️" shortcut="⌘E" value="rename">Rename</nk-menu-item>
// <nk-menu-item type="separator"></nk-menu-item>   <nk-menu-item type="label">Danger</nk-menu-item>
// <nk-menu-item icon="🗑️" danger value="delete">Delete</nk-menu-item>
// → <div class="nk-menu-item danger"><span class="m-icon">🗑️</span>Delete<span class="m-shortcut">…</span></div>
class NkMenuItem extends NkElement {
  static get observedAttributes() { return ['icon', 'shortcut', 'danger', 'value', 'type', 'disabled']; }

  render() { this._build(); }

  _build() {
    const type = this.getAttribute('type');
    let el;
    if (type === 'separator') {
      el = this.createElement('div', ['nk-menu-sep'], { role: 'separator' });
    } else if (type === 'label') {
      el = this.createElement('div', ['nk-menu-label']);
      el.appendChild(document.createElement('slot'));
    } else {
      el = this.createElement('div', ['nk-menu-item'], { role: 'menuitem', tabindex: '-1' });
      this._icon = this.createElement('span', ['m-icon']);
      const iconSlot = this.createElement('slot', [], { name: 'icon' });
      iconSlot.appendChild(this._icon);
      this._shortcut = this.createElement('span', ['m-shortcut']);
      el.append(iconSlot, document.createElement('slot'), this._shortcut);
    }
    if (this._el) { this._el.removeEventListener('click', this._onClick); this._el.replaceWith(el); } else this._wrapper.appendChild(el);
    this._el = el;
    if (this._onClick) el.addEventListener('click', this._onClick);
    this._sync();
  }

  _sync() {
    if (!this._el.classList.contains('nk-menu-item')) return;
    const icon = this.getAttribute('icon');
    this._icon.textContent = icon || '';
    this._icon.style.display = icon ? '' : 'none';
    const sc = this.getAttribute('shortcut');
    this._shortcut.textContent = sc || '';
    this._shortcut.style.display = sc ? '' : 'none';
    this._el.classList.toggle('danger', this.getBoolAttr('danger'));
    this._el.setAttribute('aria-disabled', this.getBoolAttr('disabled') ? 'true' : 'false');
  }

  setupEvents() {
    this._onClick = () => this.select();
    this._el.addEventListener('click', this._onClick);
  }

  teardownEvents() { this._el?.removeEventListener('click', this._onClick); }

  select() {
    if (!this._el.classList.contains('nk-menu-item') || this.getBoolAttr('disabled')) return;
    this.emit('nk-select', { value: this.value, label: this.textContent.trim(), item: this });
  }

  onAttributeChanged(name) { name === 'type' ? this._build() : this._sync(); }
  focus(o) { this._el?.focus(o); }
  get selectable() { return this._el?.classList.contains('nk-menu-item') && !this.getBoolAttr('disabled'); }

  get value() { return this.getAttribute('value') ?? this.textContent.trim(); }
  set value(v) { this.setAttribute('value', v); }
}

customElements.define('nk-menu-item', NkMenuItem);

// <nk-pop placement="bottom-start">
//   <nk-btn slot="trigger" variant="secondary">Options</nk-btn>
//   <nk-menu>…</nk-menu>
// </nk-pop>
// The trigger stays in the light DOM; a click on it toggles `open`, outside
// clicks and Escape close. Content is wrapped in `.nk-pop` unless it brings
// its own surface (nk-menu, nk-emoji-picker) or `bare` is set. The only
// styling here is positioning – the surface look is the stylesheet's.
const popSheet = new CSSStyleSheet();
popSheet.replaceSync(`
  .nk-pop-anchor { position: relative; display: inline-block; }
  .nk-pop-float { display: none; position: absolute; z-index: 50; top: 100%; left: 0; margin-top: 4px; }
  :host([open]) .nk-pop-float { display: block; }
  :host([placement="bottom-end"]) .nk-pop-float { left: auto; right: 0; }
  :host([placement="top-start"]) .nk-pop-float { top: auto; bottom: 100%; margin: 0 0 4px; }
  :host([placement="top-end"]) .nk-pop-float { top: auto; bottom: 100%; left: auto; right: 0; margin: 0 0 4px; }
`);
const OWN_SURFACE = new Set(['nk-menu', 'nk-emoji-picker']);

class NkPop extends NkElement {
  static get hostStyles() { return popSheet; }
  static get observedAttributes() { return ['open', 'placement', 'bare']; }

  render() {
    const anchor = this.createElement('div', ['nk-pop-anchor']);
    this._triggerSlot = this.createElement('slot', [], { name: 'trigger' });
    this._float = this.createElement('div', ['nk-pop-float']);
    this._surface = this.createElement('div', ['nk-pop']);
    this._slot = document.createElement('slot');
    this._surface.appendChild(this._slot);
    this._float.appendChild(this._surface);
    anchor.append(this._triggerSlot, this._float);
    this._wrapper.appendChild(anchor);
    this._syncSurface();
  }

  _syncSurface() {
    const bare = this.getBoolAttr('bare') || this._slot.assignedElements().some(el => OWN_SURFACE.has(el.localName));
    this._surface.className = bare ? '' : 'nk-pop';
  }

  setupEvents() {
    this._onTrigger = (e) => {
      if (!e.composedPath().some(n => n instanceof Element && n.getAttribute?.('slot') === 'trigger')) return;
      e.stopPropagation();
      this.toggle();
    };
    this._onDocClick = (e) => { if (this.getBoolAttr('open') && !e.composedPath().includes(this)) this.close(); };
    this._onKey = (e) => { if (e.key === 'Escape' && this.getBoolAttr('open')) this.close(); };
    this._onSelect = (e) => { if (e.target !== this) this.close(); };
    this._onSlot = () => this._syncSurface();
    this.addEventListener('click', this._onTrigger);
    document.addEventListener('click', this._onDocClick);
    document.addEventListener('keydown', this._onKey);
    this._float.addEventListener('nk-select', this._onSelect);
    this._slot.addEventListener('slotchange', this._onSlot);
  }

  teardownEvents() {
    this.removeEventListener('click', this._onTrigger);
    document.removeEventListener('click', this._onDocClick);
    document.removeEventListener('keydown', this._onKey);
    this._float?.removeEventListener('nk-select', this._onSelect);
    this._slot?.removeEventListener('slotchange', this._onSlot);
  }

  onAttributeChanged(name) {
    if (name === 'bare') this._syncSurface();
    if (name === 'open') {
      const open = this.getBoolAttr('open');
      for (const el of this._triggerSlot.assignedElements()) el.setAttribute('aria-expanded', open ? 'true' : 'false');
      this.emit('nk-toggle', { open });
    }
  }

  show() { this.setBoolAttr('open', true); }
  close() { this.setBoolAttr('open', false); }
  toggle() { this.setBoolAttr('open', !this.getBoolAttr('open')); }

  get open() { return this.getBoolAttr('open'); }
  set open(v) { this.setBoolAttr('open', v); }
  get placement() { return this.getAttribute('placement') || 'bottom-start'; }
  set placement(v) { this.setAttribute('placement', v); }
}

customElements.define('nk-pop', NkPop);

// Built-in emoji set for <nk-emoji-picker>: eight categories, names for
// search. Override with `picker.emojis = [{ char, name, cat }]`.
