// <nk-emoji-picker></nk-emoji-picker>
// → <div class="nk-pop"><input class="nk-emoji-search"><div class="nk-emoji-grid">…</div><div class="nk-emoji-cats">…</div></div>
// Built-in set with names for search; `picker.emojis = [{ char, name, cat }]`
// replaces it. A click fires nk-select { emoji }.
class NkEmojiPicker extends NkElement {
  static get observedAttributes() { return ['placeholder', 'value']; }

  render() {
    this._box = this.createElement('div', ['nk-pop']);
    this._search = this.createElement('input', ['nk-emoji-search'], { type: 'search', autocomplete: 'off', 'aria-label': 'Search emoji' });
    this._grid = this.createElement('div', ['nk-emoji-grid'], { role: 'listbox' });
    this._cats = this.createElement('div', ['nk-emoji-cats'], { role: 'tablist' });
    this._box.append(this._search, this._grid, this._cats);
    this._wrapper.appendChild(this._box);
    this._emojis = EMOJI;
    this._cat = EMOJI_CATEGORIES[0].id;
    this._renderCats();
    this._renderGrid();
    this._syncAttrs();
  }

  _syncAttrs() { this._search.placeholder = this.getAttribute('placeholder') || 'Search…'; }

  _renderCats() {
    this._cats.replaceChildren();
    const cats = this._categories();
    for (const cat of cats) {
      const el = this.createElement('span', [], { role: 'tab', 'data-cat': cat.id, title: cat.id });
      el.textContent = cat.icon;
      el.classList.toggle('active', cat.id === this._cat);
      this._cats.appendChild(el);
    }
    this._cats.style.display = cats.length > 1 ? '' : 'none';
  }

  _categories() {
    if (this._catList) return this._catList;
    const seen = new Map();
    for (const e of this._emojis) if (e.cat && !seen.has(e.cat)) seen.set(e.cat, { id: e.cat, icon: e.icon || EMOJI_CATEGORIES.find(c => c.id === e.cat)?.icon || e.char });
    return [...seen.values()];
  }

  _renderGrid() {
    const q = this._search.value.trim().toLowerCase();
    const list = q ? this._emojis.filter(e => (e.name || '').toLowerCase().includes(q) || e.char === q) : this._emojis.filter(e => !e.cat || e.cat === this._cat);
    this._grid.replaceChildren();
    for (const e of list.slice(0, 64)) {
      const s = this.createElement('span', [], { role: 'option', title: e.name || '', 'data-emoji': e.char });
      s.textContent = e.char;
      this._grid.appendChild(s);
    }
    for (const el of this._cats.children) el.classList.toggle('active', !q && el.dataset.cat === this._cat);
  }

  setupEvents() {
    this._onInput = () => this._renderGrid();
    this._onGrid = (e) => { const s = e.target.closest('[data-emoji]'); if (s) this.select(s.dataset.emoji); };
    this._onCats = (e) => { const c = e.target.closest('[data-cat]'); if (!c) return; this._cat = c.dataset.cat; this._search.value = ''; this._renderGrid(); };
    this._onKey = (e) => { if (e.key === 'Enter') { const first = this._grid.querySelector('[data-emoji]'); if (first) this.select(first.dataset.emoji); } };
    this._search.addEventListener('input', this._onInput);
    this._search.addEventListener('keydown', this._onKey);
    this._grid.addEventListener('click', this._onGrid);
    this._cats.addEventListener('click', this._onCats);
  }

  teardownEvents() {
    this._search?.removeEventListener('input', this._onInput);
    this._search?.removeEventListener('keydown', this._onKey);
    this._grid?.removeEventListener('click', this._onGrid);
    this._cats?.removeEventListener('click', this._onCats);
  }

  select(emoji) {
    this.setAttribute('value', emoji);
    this.emit('nk-select', { emoji, value: emoji });
  }

  onAttributeChanged() { this._syncAttrs(); }
  focus(o) { this._search?.focus(o); }

  /** Category strip override: [{ id, icon }]. Emojis without `cat` show in every category. */
  get categories() { return this._categories(); }
  set categories(list) { this._catList = Array.isArray(list) && list.length ? list : null; this._cat = this._categories()[0]?.id; this._renderCats(); this._renderGrid(); }
  get emojis() { return this._emojis; }
  set emojis(list) { this._emojis = Array.isArray(list) ? list : EMOJI; this._cat = this._categories()[0]?.id; this._renderCats(); this._renderGrid(); }
  get value() { return this.getAttribute('value'); }
  set value(v) { this.setAttribute('value', v); }
}

customElements.define('nk-emoji-picker', NkEmojiPicker);

// <nk-toast id="toast"></nk-toast>   …   toast.show('Saved');
// → <div class="nk-toast show">✓ Saved</div>
// One node, bottom-centred, auto-hides after `duration` ms (default 2200).
class NkToast extends NkElement {
  static get observedAttributes() { return ['open', 'duration', 'icon']; }

  render() {
    this._box = this.createElement('div', ['nk-toast'], { role: 'status', 'aria-live': 'polite' });
    this._icon = document.createElement('span');
    this._msg = document.createElement('span');
    this._box.append(this._icon, this._msg, document.createElement('slot'));
    this._wrapper.appendChild(this._box);
    this._sync();
  }

  _sync() {
    this._box.classList.toggle('show', this.getBoolAttr('open'));
    const icon = this.getAttribute('icon') ?? '✓';
    this._icon.textContent = icon;
    this._icon.style.display = icon ? '' : 'none';
  }

  /** Shows `message` (or the slotted content when omitted) and hides it again after `duration`. */
  show(message, { duration } = {}) {
    if (message !== undefined) this._msg.textContent = message;
    clearTimeout(this._timer);
    this.setBoolAttr('open', true);
    const ms = duration ?? Number(this.getAttribute('duration')) ?? 2200;
    if (ms > 0) this._timer = setTimeout(() => this.close(), ms || 2200);
  }

  close() { clearTimeout(this._timer); this.setBoolAttr('open', false); }

  onAttributeChanged(name) {
    this._sync();
    if (name === 'open') this.emit('nk-toggle', { open: this.getBoolAttr('open') });
  }

  disconnectedCallback() { super.disconnectedCallback(); clearTimeout(this._timer); }

  get open() { return this.getBoolAttr('open'); }
  set open(v) { this.setBoolAttr('open', v); }
  get message() { return this._msg?.textContent ?? ''; }
  set message(v) { if (this._msg) this._msg.textContent = v; }
}

customElements.define('nk-toast', NkToast);

// <nk-database id="db" view="table" add-view>
//   <nk-table-view name="table" label="▦ Table" count></nk-table-view>
//   <nk-board-view name="board" label="▤ Board" group-by="status"></nk-board-view>
// </nk-database>
// db.columns = [{ key: 'name', label: 'Name', type: 'text', icon: '📄', title: true }, { key: 'status', type: 'select', options: [...] }, …];
// db.rows = [{ id: 1, icon: '🧭', name: '…', status: 'done', … }];
// → <div class="nk-database"><div class="nk-db-tabs">…</div>…active view…</div>
// The tabs come from the child views; data is pushed into every view.
class NkDatabase extends NkElement {
  static get observedAttributes() { return ['view', 'add-view']; }

  render() {
    this._box = this.createElement('div', ['nk-database']);
    this._tabs = this.createElement('div', ['nk-db-tabs'], { role: 'tablist' });
    this._slot = document.createElement('slot');
    this._box.append(this._tabs, this._slot);
    this._wrapper.appendChild(this._box);
    this._columns = []; this._rows = [];
    this._sync();
  }

  get views() { return this._slot?.assignedElements().filter(el => /^nk-[a-z]+-view$/.test(el.localName)) ?? []; }

  _sync() {
    if (!this._tabs) return;
    const views = this.views;
    let current = this.getAttribute('view');
    if (!views.some(v => v.name === current)) current = views[0]?.name ?? null;
    this._tabs.replaceChildren();
    for (const v of views) {
      const tab = this.createElement('span', ['nk-db-tab'], { role: 'tab', 'data-view': v.name, tabindex: '0' });
      tab.classList.toggle('active', v.name === current);
      tab.setAttribute('aria-selected', v.name === current ? 'true' : 'false');
      tab.append(document.createTextNode(v.getAttribute('label') || v.name));
      const badge = v.hasAttribute('count') ? String(this._rows.length) : v.getAttribute('badge');
      if (badge) { const b = this.createElement('span', ['badge']); b.textContent = badge; tab.appendChild(b); }
      this._tabs.appendChild(tab);
      v.hidden = v.name !== current;
      // A method call, not a property write: a view that has not been upgraded
      // yet would otherwise get an own `data` property that shadows its setter.
      v.setData?.(this._columns, this._rows);
    }
    if (this.getBoolAttr('add-view')) {
      const add = this.createElement('span', ['nk-db-tab'], { role: 'button', 'data-add': '', tabindex: '0' });
      add.style.color = 'var(--nk-text-tertiary)';
      add.textContent = '＋';
      this._tabs.appendChild(add);
    }
    this._tabs.style.display = views.length ? '' : 'none';
    this._current = current;
  }

  /** Views upgrade after the database; each one asks for a resync once rendered. */
  requestSync() {
    if (this._syncQueued) return;
    this._syncQueued = true;
    queueMicrotask(() => { this._syncQueued = false; this._sync(); });
  }

  setupEvents() {
    this._onClick = (e) => {
      const tab = e.target.closest('[data-view]');
      if (tab) { this.view = tab.dataset.view; return; }
      if (e.target.closest('[data-add]')) this.emit('nk-action', { action: 'add-view' });
    };
    this._onKey = (e) => { if ((e.key === 'Enter' || e.key === ' ') && e.target.closest('[data-view],[data-add]')) { e.preventDefault(); e.target.click(); } };
    this._onSlot = () => this._sync();
    this._tabs.addEventListener('click', this._onClick);
    this._tabs.addEventListener('keydown', this._onKey);
    this._slot.addEventListener('slotchange', this._onSlot);
    this._sync();
  }

  teardownEvents() {
    this._tabs?.removeEventListener('click', this._onClick);
    this._tabs?.removeEventListener('keydown', this._onKey);
    this._slot?.removeEventListener('slotchange', this._onSlot);
  }

  onAttributeChanged(name) {
    const before = this._current;
    this._sync();
    if (name === 'view' && this._current !== before) this.emit('nk-view-change', { view: this._current });
  }

  get columns() { return this._columns; }
  set columns(v) { this._columns = Array.isArray(v) ? v : []; this._sync(); }
  get rows() { return this._rows; }
  set rows(v) { this._rows = Array.isArray(v) ? v : []; this._sync(); }
  get view() { return this._current ?? this.getAttribute('view'); }
  set view(v) { this.setAttribute('view', v); }
  /** Re-renders every view after in-place row mutations. */
  refresh() { this._sync(); }
}

customElements.define('nk-database', NkDatabase);

// Polymorphic property renderer for database views. Returns plain DOM built
// from NotionKit classes – deliberately not a custom element: every cell rule
// starts with `.nk-table`, so a cell inside its own shadow root would never
// be styled. Exported for consumers who render tables themselves.
//
// column: { key, label, type, icon, options: [{ value, label, color }], title }
// types: text | select | multi-select | date | person | checkbox | url | number | progress
const el = (tag, cls, text) => { const n = document.createElement(tag); if (cls) n.className = cls; if (text != null) n.textContent = text; return n; };
const COLORS = ['blue', 'green', 'orange', 'purple'];

function optionFor(column, value) {
  const opts = column.options || [];
  return opts.find(o => o.value === value) || opts.find(o => o.label === value) || null;
}

function tagFor(column, value) {
  const opt = optionFor(column, value);
  const color = opt?.color && COLORS.includes(opt.color) ? opt.color : 'blue';
  return el('span', `nk-tag ${color}`, opt?.label ?? String(value));
}

function renderPropertyCell(column, value, row = {}) {
  const type = column.type || 'text';
  if (value === undefined || value === null || value === '') {
    if (type === 'checkbox') return checkbox(column, false, row);
    if (type === 'progress') return progress(0);
    return el('span', type === 'person' ? 'person-cell' : null, type === 'text' && column.title ? '' : '—');
  }
  switch (type) {
    case 'select': return tagFor(column, value);
    case 'multi-select': {
      const wrap = el('span');
      wrap.style.display = 'inline-flex'; wrap.style.gap = '4px'; wrap.style.flexWrap = 'wrap';
      for (const v of Array.isArray(value) ? value : String(value).split(',').map(s => s.trim()).filter(Boolean)) wrap.appendChild(tagFor(column, v));
      return wrap;
    }
    case 'date': return el('span', 'date-cell', String(value));
    case 'person': {
      const cell = el('span', 'person-cell');
      const p = typeof value === 'string' ? { name: value } : value;
      const avatar = el('span', 'mini-avatar', p.initials || p.avatar || (p.name || '').split(/\s+/).map(w => w[0]).join('').slice(0, 2).toUpperCase());
      avatar.style.background = p.color || 'var(--nk-text-tertiary)';
      cell.append(avatar, document.createTextNode(' ' + (p.name || '')));
      return cell;
    }
    case 'checkbox': return checkbox(column, !!value, row);
    case 'url': { const a = el('a', null, String(value).replace(/^https?:\/\//, '')); a.href = String(value); a.target = '_blank'; a.rel = 'noopener'; return a; }
    case 'number': return el('span', null, typeof value === 'number' ? value.toLocaleString() : String(value));
    case 'progress': return progress(Number(value) || 0);
    default: {
      if (column.title) {
        const t = el('span', 'row-title');
        if (row.icon) t.append(document.createTextNode(row.icon + ' '));
        t.append(document.createTextNode(String(value)));
        return t;
      }
      return el('span', null, String(value));
    }
  }
}

function checkbox(column, checked, row) {
  const label = el('label', 'nk-check');
  const input = el('input');
  input.type = 'checkbox'; input.checked = checked;
  input.dataset.key = column.key;
  if (row.id != null) input.dataset.rowId = row.id;
  label.appendChild(input);
  return label;
}

function progress(value) {
  const frag = document.createDocumentFragment();
  const bar = el('span', 'nk-progress');
  const fill = el('i'); fill.style.width = `${Math.max(0, Math.min(100, value))}%`;
  bar.appendChild(fill);
  frag.append(bar, el('span', 'nk-progress-label', `${Math.round(value)}%`));
  return frag;
}

/** Sort comparator for a column type. */
function compareBy(column, dir = 1) {
  const type = column.type || 'text';
  return (a, b) => {
    let x = a[column.key], y = b[column.key];
    if (type === 'person') { x = x?.name ?? x ?? ''; y = y?.name ?? y ?? ''; }
    if (type === 'number' || type === 'progress' || type === 'checkbox') return ((Number(x) || 0) - (Number(y) || 0)) * dir;
    return String(x ?? '').localeCompare(String(y ?? ''), undefined, { numeric: true }) * dir;
  };
}

// <nk-table-view name="table" label="▦ Table" count new-row sortable></nk-table-view>
// Standalone: view.columns = […]; view.rows = […];  Inside <nk-database> the
// database pushes `data`. → <div class="nk-table-wrap"><table class="nk-table">…</table><div class="nk-new-row">＋ New page</div></div>
// Cells are plain markup from renderPropertyCell(); rows fire nk-select,
// checkboxes nk-change, headers nk-action { action: 'sort' } (and sort locally
// with `sortable`), the add row nk-action { action: 'new-row' }.
class NkTableView extends NkElement {
  static get observedAttributes() { return ['name', 'label', 'badge', 'count', 'new-row', 'new-row-label', 'sortable', 'sort-key', 'sort-dir']; }

  render() {
    this._wrap = this.createElement('div', ['nk-table-wrap']);
    this._table = this.createElement('table', ['nk-table']);
    this._thead = document.createElement('thead');
    this._tbody = document.createElement('tbody');
    this._table.append(this._thead, this._tbody);
    this._newRow = this.createElement('div', ['nk-new-row'], { role: 'button', tabindex: '0' });
    this._wrap.append(this._table, this._newRow);
    this._wrapper.appendChild(this._wrap);
    this._columns ??= []; this._rows ??= [];
    this._render();
    this.closest('nk-database')?.requestSync?.();
  }

  _sortedRows() {
    const key = this.getAttribute('sort-key');
    const col = this._columns.find(c => c.key === key);
    if (!col) return this._rows;
    return [...this._rows].sort(compareBy(col, this.getAttribute('sort-dir') === 'desc' ? -1 : 1));
  }

  _render() {
    if (!this._thead) return;
    const tr = document.createElement('tr');
    for (const col of this._columns) {
      const th = this.createElement('th', [], { 'data-key': col.key, scope: 'col' });
      if (col.icon) { const i = this.createElement('span', ['th-icon']); i.textContent = col.icon; th.appendChild(i); }
      th.appendChild(document.createTextNode(col.label ?? col.key));
      if (col.key === this.getAttribute('sort-key')) th.appendChild(document.createTextNode(this.getAttribute('sort-dir') === 'desc' ? ' ↓' : ' ↑'));
      if (col.width) th.style.width = col.width;
      tr.appendChild(th);
    }
    this._thead.replaceChildren(tr);
    this._tbody.replaceChildren();
    for (const row of this._sortedRows()) {
      const r = this.createElement('tr', [], { 'data-id': row.id ?? '' });
      for (const col of this._columns) {
        const td = document.createElement('td');
        td.appendChild(renderPropertyCell(col, row[col.key], row));
        r.appendChild(td);
      }
      this._tbody.appendChild(r);
    }
    this._newRow.textContent = this.getAttribute('new-row-label') || '＋ New page';
    this._newRow.style.display = this.getBoolAttr('new-row') ? '' : 'none';
  }

  setupEvents() {
    this._onClick = (e) => {
      if (this._newRow.contains(e.target)) { this.emit('nk-action', { action: 'new-row' }); return; }
      const th = e.target.closest('th[data-key]');
      if (th) {
        const key = th.dataset.key;
        const dir = this.getAttribute('sort-key') === key && this.getAttribute('sort-dir') !== 'desc' ? 'desc' : 'asc';
        const ok = this.emit('nk-action', { action: 'sort', key, value: dir });
        if (ok && this.getBoolAttr('sortable')) { this.setAttribute('sort-key', key); this.setAttribute('sort-dir', dir); }
        return;
      }
      if (e.target.closest('input[type=checkbox], a')) return;
      const tr = e.target.closest('tr[data-id]');
      if (tr) { const row = this._rowById(tr.dataset.id); this.emit('nk-select', { row, id: row?.id, value: row?.id }); }
    };
    this._onChange = (e) => {
      const input = e.target;
      if (input.type !== 'checkbox') return;
      const row = this._rowById(input.dataset.rowId);
      if (row) row[input.dataset.key] = input.checked;
      this.emit('nk-change', { row, key: input.dataset.key, value: input.checked });
    };
    this._onKey = (e) => { if ((e.key === 'Enter' || e.key === ' ') && e.target === this._newRow) { e.preventDefault(); this.emit('nk-action', { action: 'new-row' }); } };
    this._wrap.addEventListener('click', this._onClick);
    this._wrap.addEventListener('change', this._onChange);
    this._wrap.addEventListener('keydown', this._onKey);
  }

  teardownEvents() {
    this._wrap?.removeEventListener('click', this._onClick);
    this._wrap?.removeEventListener('change', this._onChange);
    this._wrap?.removeEventListener('keydown', this._onKey);
  }

  _rowById(id) { return this._rows.find(r => String(r.id) === String(id)); }
  onAttributeChanged() { this._render(); }

  get name() { return this.getAttribute('name') || 'table'; }
  get columns() { return this._columns; }
  set columns(v) { this._columns = Array.isArray(v) ? v : []; this._render(); }
  get rows() { return this._rows; }
  set rows(v) { this._rows = Array.isArray(v) ? v : []; this._render(); }
  set data({ columns, rows }) { this.setData(columns, rows); }
  setData(columns, rows) { this._columns = columns || []; this._rows = rows || []; this._render(); }
  refresh() { this._render(); }
}

customElements.define('nk-table-view', NkTableView);

// <nk-board-view name="board" label="▤ Board" group-by="status" new-row></nk-board-view>
// Groups rows by a select column (default: the first select column); one
// column per option, in option order. Cards show the title column and the
// `meta-keys` (default: date and progress columns). Drag a card onto another
// column to change its value – the row is updated and nk-change fires.
// → <div class="nk-board active"><div class="nk-board-col">…</div>…</div>
class NkBoardView extends NkElement {
  static get observedAttributes() { return ['name', 'label', 'badge', 'count', 'group-by', 'title-key', 'meta-keys', 'new-row']; }

  render() {
    this._board = this.createElement('div', ['nk-board', 'active']);
    this._wrapper.appendChild(this._board);
    this._columns ??= []; this._rows ??= [];
    this._render();
    this.closest('nk-database')?.requestSync?.();
  }

  _groupColumn() {
    const key = this.getAttribute('group-by');
    return this._columns.find(c => c.key === key) || this._columns.find(c => c.type === 'select') || null;
  }
  _titleColumn() {
    const key = this.getAttribute('title-key');
    return this._columns.find(c => c.key === key) || this._columns.find(c => c.title) || this._columns[0] || null;
  }
  _metaColumns() {
    const keys = (this.getAttribute('meta-keys') || '').split(',').map(s => s.trim()).filter(Boolean);
    if (keys.length) return keys.map(k => this._columns.find(c => c.key === k)).filter(Boolean);
    return this._columns.filter(c => c.type === 'date' || c.type === 'progress');
  }

  _render() {
    if (!this._board) return;
    this._board.replaceChildren();
    const group = this._groupColumn(), title = this._titleColumn();
    if (!group) return;
    const options = group.options?.length ? group.options : [...new Set(this._rows.map(r => r[group.key]))].map(v => ({ value: v, label: String(v) }));
    for (const opt of options) {
      const col = this.createElement('div', ['nk-board-col'], { 'data-value': opt.value });
      const header = this.createElement('div', ['nk-board-col-header']);
      const cards = this._rows.filter(r => r[group.key] === opt.value || r[group.key] === opt.label);
      const count = this.createElement('span', ['count']);
      count.textContent = String(cards.length);
      header.append(tagFor(group, opt.value), count);
      col.appendChild(header);
      for (const row of cards) {
        const card = this.createElement('div', ['nk-card'], { draggable: 'true', 'data-id': row.id ?? '', tabindex: '0' });
        const t = this.createElement('div', ['card-title']);
        t.textContent = `${row.icon ? row.icon + ' ' : ''}${title ? row[title.key] ?? '' : ''}`;
        const meta = this.createElement('div', ['card-meta']);
        for (const c of this._metaColumns()) {
          const v = row[c.key];
          if (v === undefined || v === null || v === '') continue;
          const s = document.createElement('span');
          if (c.type === 'progress') s.textContent = `▰ ${v}%`;
          else if (c.type === 'date') s.textContent = `📅 ${v}`;
          else s.appendChild(renderPropertyCell(c, v, row));
          meta.appendChild(s);
        }
        card.append(t, meta);
        col.appendChild(card);
      }
      if (this.getBoolAttr('new-row')) {
        const add = this.createElement('div', ['nk-new-row'], { role: 'button', tabindex: '0', 'data-add': opt.value });
        add.style.padding = '6px 10px';
        add.textContent = '＋';
        col.appendChild(add);
      }
      this._board.appendChild(col);
    }
  }

  setupEvents() {
    this._onClick = (e) => {
      const add = e.target.closest('[data-add]');
      if (add) { this.emit('nk-action', { action: 'new-row', value: add.dataset.add }); return; }
      const card = e.target.closest('.nk-card');
      if (card) { const row = this._rowById(card.dataset.id); this.emit('nk-select', { row, id: row?.id, value: row?.id }); }
    };
    this._onDragStart = (e) => { const card = e.target.closest?.('.nk-card'); if (!card) return; this._dragId = card.dataset.id; e.dataTransfer.effectAllowed = 'move'; try { e.dataTransfer.setData('text/plain', card.dataset.id); } catch {} };
    this._onDragOver = (e) => { if (this._dragId != null && e.target.closest('.nk-board-col')) { e.preventDefault(); e.dataTransfer.dropEffect = 'move'; } };
    this._onDrop = (e) => {
      const col = e.target.closest('.nk-board-col');
      if (!col || this._dragId == null) return;
      e.preventDefault();
      this.move(this._dragId, col.dataset.value);
      this._dragId = null;
    };
    this._board.addEventListener('click', this._onClick);
    this._board.addEventListener('dragstart', this._onDragStart);
    this._board.addEventListener('dragover', this._onDragOver);
    this._board.addEventListener('drop', this._onDrop);
  }

  teardownEvents() {
    this._board?.removeEventListener('click', this._onClick);
    this._board?.removeEventListener('dragstart', this._onDragStart);
    this._board?.removeEventListener('dragover', this._onDragOver);
    this._board?.removeEventListener('drop', this._onDrop);
  }

  /** Moves a row into another column (sets the group value) and reports it. */
  move(id, value) {
    const row = this._rowById(id), group = this._groupColumn();
    if (!row || !group || row[group.key] === value) return;
    row[group.key] = value;
    this._render();
    this.emit('nk-change', { row, key: group.key, value });
  }

  _rowById(id) { return this._rows.find(r => String(r.id) === String(id)); }
  onAttributeChanged() { this._render(); }

  get name() { return this.getAttribute('name') || 'board'; }
  get columns() { return this._columns; }
  set columns(v) { this._columns = Array.isArray(v) ? v : []; this._render(); }
  get rows() { return this._rows; }
  set rows(v) { this._rows = Array.isArray(v) ? v : []; this._render(); }
  set data({ columns, rows }) { this.setData(columns, rows); }
  setData(columns, rows) { this._columns = columns || []; this._rows = rows || []; this._render(); }
  refresh() { this._render(); }
}

customElements.define('nk-board-view', NkBoardView);

// <nk-filter-bar search placeholder="Search rows …"></nk-filter-bar>
// bar.filters = [{ key: 'status', label: 'Status: Done', value: 'done' }];
// Composed from existing classes (nk-btn secondary small, nk-input, nk-tag):
// filter / sort buttons fire nk-action, chips remove on ×, search and chip
// changes fire nk-change { filters, search }. The wrapper is layout only.
class NkFilterBar extends NkElement {
  static get observedAttributes() { return ['search', 'placeholder', 'no-filter', 'no-sort', 'value']; }

  render() {
    this._bar = document.createElement('div');
    this._bar.style.cssText = 'display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin:8px 0';
    this._filterBtn = this.createElement('button', ['nk-btn', 'secondary', 'small'], { type: 'button', 'data-action': 'filter' });
    this._filterBtn.textContent = '⚲ Filter';
    this._sortBtn = this.createElement('button', ['nk-btn', 'secondary', 'small'], { type: 'button', 'data-action': 'sort' });
    this._sortBtn.textContent = '↕ Sort';
    this._chips = document.createElement('span');
    this._chips.style.cssText = 'display:inline-flex;gap:4px;flex-wrap:wrap';
    this._input = this.createElement('input', ['nk-input'], { type: 'search', autocomplete: 'off' });
    this._input.style.marginLeft = 'auto';
    this._bar.append(this._filterBtn, this._sortBtn, this._chips, document.createElement('slot'), this._input);
    this._wrapper.appendChild(this._bar);
    this._filters = [];
    this._sync();
  }

  _sync() {
    this._filterBtn.style.display = this.getBoolAttr('no-filter') ? 'none' : '';
    this._sortBtn.style.display = this.getBoolAttr('no-sort') ? 'none' : '';
    this._input.style.display = this.getBoolAttr('search') ? '' : 'none';
    this._input.placeholder = this.getAttribute('placeholder') || 'Search …';
    if (this.hasAttribute('value') && this._input.value !== this.getAttribute('value')) this._input.value = this.getAttribute('value');
    this._chips.replaceChildren();
    this._filters.forEach((f, i) => {
      const chip = this.createElement('span', ['nk-tag', f.color || 'blue'], { 'data-index': i });
      chip.style.cursor = 'pointer';
      chip.textContent = `${f.label ?? `${f.key}: ${f.value}`} ×`;
      chip.title = 'Remove filter';
      this._chips.appendChild(chip);
    });
  }

  setupEvents() {
    this._onClick = (e) => {
      const btn = e.target.closest('[data-action]');
      if (btn) { this.emit('nk-action', { action: btn.dataset.action }); return; }
      const chip = e.target.closest('[data-index]');
      if (chip) { this._filters.splice(Number(chip.dataset.index), 1); this._sync(); this._emitChange(); }
    };
    this._onInput = () => { clearTimeout(this._debounce); this._debounce = setTimeout(() => this._emitChange(), 150); };
    this._bar.addEventListener('click', this._onClick);
    this._input.addEventListener('input', this._onInput);
  }

  teardownEvents() {
    this._bar?.removeEventListener('click', this._onClick);
    this._input?.removeEventListener('input', this._onInput);
    clearTimeout(this._debounce);
  }

  _emitChange() { this.emit('nk-change', { filters: [...this._filters], search: this._input.value }); }
  onAttributeChanged() { this._sync(); }

  get filters() { return this._filters; }
  set filters(v) { this._filters = Array.isArray(v) ? v : []; this._sync(); }
  get value() { return this._input?.value ?? ''; }
  set value(v) { if (this._input) this._input.value = v ?? ''; }
  /** Applies filters + search to rows: equality per filter key, substring search over every string field. */
  apply(rows) {
    const q = this.value.trim().toLowerCase();
    return rows.filter(r => this._filters.every(f => r[f.key] === f.value) && (!q || Object.values(r).some(v => String(typeof v === 'object' && v ? v.name ?? '' : v ?? '').toLowerCase().includes(q))));
  }
}

customElements.define('nk-filter-bar', NkFilterBar);

// <nk-comments placeholder="Comment …" send-label="Send">
//   <nk-comment …>…</nk-comment>
// </nk-comments>
// → <div class="nk-comments">…<div class="nk-comment-input"><input class="nk-input"><button class="nk-btn primary small">Send</button></div></div>
// Enter or the button fires nk-submit { text } and clears the field.
class NkComments extends NkElement {
  static get observedAttributes() { return ['placeholder', 'send-label', 'no-input', 'disabled']; }

  render() {
    const box = this.createElement('div', ['nk-comments']);
    box.appendChild(document.createElement('slot'));
    this._row = this.createElement('div', ['nk-comment-input']);
    this._input = this.createElement('input', ['nk-input'], { type: 'text', 'aria-label': 'Comment' });
    this._btn = this.createElement('button', ['nk-btn', 'primary', 'small'], { type: 'button' });
    this._row.append(this._input, this._btn);
    box.appendChild(this._row);
    this._wrapper.appendChild(box);
    this._sync();
  }

  _sync() {
    this._input.placeholder = this.getAttribute('placeholder') || 'Comment …';
    this._btn.textContent = this.getAttribute('send-label') || 'Send';
    this._row.style.display = this.getBoolAttr('no-input') ? 'none' : '';
    this._input.disabled = this._btn.disabled = this.getBoolAttr('disabled');
  }

  setupEvents() {
    this._onSend = () => this.submit();
    this._onKey = (e) => { if (e.key === 'Enter') { e.preventDefault(); this.submit(); } };
    this._btn.addEventListener('click', this._onSend);
    this._input.addEventListener('keydown', this._onKey);
  }

  teardownEvents() {
    this._btn?.removeEventListener('click', this._onSend);
    this._input?.removeEventListener('keydown', this._onKey);
  }

  submit() {
    const text = this._input.value.trim();
    if (!text) return;
    const ok = this.emit('nk-submit', { text });
    if (ok) this._input.value = '';
  }

  onAttributeChanged() { this._sync(); }
  focus(o) { this._input?.focus(o); }
  get value() { return this._input?.value ?? ''; }
  set value(v) { if (this._input) this._input.value = v ?? ''; }
}

customElements.define('nk-comments', NkComments);

// <nk-comment author="Sara Lindt" time="1 hr ago" avatar="SL" color="#448361">The board view feels close.</nk-comment>
// → <div class="nk-comment"><span class="mini-avatar">SL</span><div><div class="c-head"><b>Sara Lindt</b> · 1 hr ago</div><div class="c-body">…</div></div></div>
// slot="head" adds content after the name (e.g. an <nk-tag>).
class NkComment extends NkElement {
  static get observedAttributes() { return ['author', 'time', 'avatar', 'color']; }

  render() {
    const box = this.createElement('div', ['nk-comment']);
    this._avatar = this.createElement('span', ['mini-avatar']);
    const avatarSlot = this.createElement('slot', [], { name: 'avatar' });
    avatarSlot.appendChild(this._avatar);
    const text = document.createElement('div');
    this._head = this.createElement('div', ['c-head']);
    this._author = document.createElement('b');
    this._time = document.createTextNode('');
    this._head.append(this._author, this.createElement('slot', [], { name: 'head' }), this._time);
    const body = this.createElement('div', ['c-body']);
    body.appendChild(document.createElement('slot'));
    text.append(this._head, body);
    box.append(avatarSlot, text);
    this._wrapper.appendChild(box);
    this._sync();
  }

  _sync() {
    const author = this.getAttribute('author') || '';
    this._author.textContent = author;
    const time = this.getAttribute('time');
    this._time.data = time ? ` · ${time}` : '';
    this._avatar.textContent = this.getAttribute('avatar') || author.split(/\s+/).map(w => w[0]).join('').slice(0, 2).toUpperCase();
    this._avatar.style.background = this.getAttribute('color') || 'var(--nk-text-tertiary)';
  }

  onAttributeChanged() { this._sync(); }
}

customElements.define('nk-comment', NkComment);

// <nk-ai-thread><nk-ai-msg …>…</nk-ai-msg>…</nk-ai-thread>  →  <div class="nk-ai-thread">
